   105→  TVEventHandler = null;
   106→}
   107→
   108→// =============================================================================
   109→// Hook Implementation
   110→// =============================================================================
   111→
   112→/**
   113→ * Hook for handling TV remote events with proper lifecycle management
   114→ *
   115→ * @param callback - Function to call when a TV remote event is received
   116→ * @param options - Optional configuration for the handler
   117→ * @returns void
   118→ *
   119→ * @remarks
   120→ * - The callback should be memoized with useCallback for best performance
   121→ * - Handler is automatically enabled on mount and disabled on unmount
   122→ * - Handles missing TVEventHandler gracefully (does nothing on non-TV platforms)
   123→ */
   124→export function useTVEventHandler(
   125→  callback: TVEventCallback,
   126→  options: UseTVEventHandlerOptions = {}
   127→): void {
   128→  const { enabled = true } = options;
   129→
   130→  // Store the handler instance in a ref to persist across renders
   131→  const tvEventHandlerRef = useRef<any>(null);
   132→
   133→  // Store the enabled state in a ref for the cleanup function
   134→  const enabledRef = useRef(enabled);
   135→  enabledRef.current = enabled;
   136→
   137→  // Memoize the internal callback to prevent unnecessary re-subscriptions
   138→  const internalCallback = useCallback(
   139→    (_component: any, event: TVRemoteEvent) => {
   140→      // Only call the callback if enabled
   141→      if (enabledRef.current && callback) {
   142→        callback(event);
   143→      }
   144→    },
   145→    [callback]
   146→  );
   147→
   148→  useEffect(() => {
   149→    // Skip setup if not on TV platform or TVEventHandler is not available
   150→    if (!Platform.isTV) {
   151→      return;
   152→    }
   153→
   154→    // Critical: Check TVEventHandler existence before instantiation
   155→    // TVEventHandler may not exist in all Expo/React Native builds
   156→    if (!TVEventHandler) {
   157→      return;
   158→    }
   159→
   160→    // Skip setup if handler is disabled
   161→    if (!enabled) {
   162→      return;
   163→    }
   164→
   165→    // Create and enable the event handler
   166→    try {
   167→      tvEventHandlerRef.current = new TVEventHandler();
   168→      tvEventHandlerRef.current.enable(null, internalCallback);
